<?php
use App\Domain\{Access,Failure};use App\Settings\Settings;use App\Reliability\Recovery;
use Illuminate\Http\Request;use Illuminate\Support\Facades\{DB,Route,RateLimiter};use Illuminate\Support\Str;
$settingsActor=function(Request $r,bool $recent=false){$u=Access::user($r->session()->get('uid'));Access::admin($u);if($recent)\App\Accounts\DeviceAuth::requireRecent($r);return $u;};
Route::get('/api/public-settings',fn()=>Settings::publicView());
Route::get('/api/admin/settings',function(Request $r)use($settingsActor){$settingsActor($r);return response()->json(Settings::adminView())->header('Cache-Control','no-store, private');});
Route::put('/api/admin/settings/{kind}',function(Request $r,string $kind)use($settingsActor){$u=$settingsActor($r,true);$v=$r->validate(['values'=>'required|array|max:30','expected_version'=>'present|nullable|uuid','confirmed'=>'required|accepted']);return Settings::save($kind,$v['values'],$v['expected_version'],$u);})->whereIn('kind',['model','oss','policies']);
Route::post('/api/admin/settings/{kind}/test',function(Request $r,string $kind)use($settingsActor){$u=$settingsActor($r,true);$r->validate(['confirmed'=>'required|accepted']);$key='connection-test:'.$u->id;if(RateLimiter::tooManyAttempts($key,3))throw new Failure('rate_limited',429);RateLimiter::hit($key,60);$version=Settings::ensureVersion($kind);$id=(string)Str::uuid();DB::table('connection_tests')->insert(['id'=>$id,'owner_id'=>$u->id,'kind'=>$kind,'settings_version'=>$version]);\App\Jobs\TestConnection::dispatch($id);return ['test'=>['id'=>$id,'kind'=>$kind,'status'=>'queued']];})->whereIn('kind',['model','oss']);
Route::get('/api/admin/connection-tests/{id}',function(Request $r,string $id)use($settingsActor){$u=$settingsActor($r);$t=DB::table('connection_tests')->where(['id'=>$id,'owner_id'=>$u->id])->first(['id','kind','status','report','failure_code','created_at','updated_at']);if(!$t)throw new Failure('connection_test_unavailable',404);$t->report=json_decode($t->report,true);return response()->json(['test'=>$t])->header('Cache-Control','no-store, private');})->whereUuid('id');
Route::get('/api/admin/diagnostics',function(Request $r)use($settingsActor){$settingsActor($r);return ['failed_queues'=>DB::table('failed_jobs')->select('queue')->selectRaw('count(*) as count')->groupBy('queue')->get(),'uploads'=>DB::table('audio_chunks')->select('storage_state')->selectRaw('count(*) as count')->groupBy('storage_state')->get(),'archive_failures'=>DB::table('lessons')->where('archive_status','failed')->count(),'issues'=>DB::table('recording_issues')->whereNull('resolved_at')->count(),'recent'=>DB::table('audit')->whereIn('action',['gateway_shutdown','translation_interrupted','lesson.purged','duration_limit','daily_audio_limit'])->orderByDesc('id')->limit(50)->get(['id','lesson_id','action','created_at'])];});
Route::post('/api/lessons/{lesson}/capture-issue',function(Request $r,int $lesson){$u=Access::user($r->session()->get('uid'));Access::member($u);Access::lesson($lesson,$u,$r->session()->getId());$key='capture-issue:'.$u->id;if(RateLimiter::tooManyAttempts($key,12))throw new Failure('rate_limited',429);RateLimiter::hit($key,60);$v=$r->validate(['epoch'=>'required|integer|min:1','reason'=>'required|in:microphone_ended,context_suspended,network_disconnected,buffer_limit,page_hidden,capture_failed','last_ack_sequence'=>'required|integer|min:-1|max:2147483646','next_sequence'=>'required|integer|min:0|max:2147483647','estimated_lost_ms'=>'nullable|integer|min:0|max:120000']);return Recovery::clientIssue($lesson,$u,$v,$r->session()->getId());})->whereNumber('lesson');
Route::get('/api/lessons/{lesson}/issues',function(Request $r,int $lesson){Access::lesson($lesson,Access::user($r->session()->get('uid')),$r->session()->getId());return ['issues'=>DB::table('recording_issues')->where('lesson_id',$lesson)->orderByDesc('id')->limit(100)->get()->map(fn($i)=>Recovery::issue($i))];})->whereNumber('lesson');
Route::get('/api/courses/{course}/subtitles',function(Request $r,int $course){$c=DB::table('courses')->where('id',$course)->where('enabled',true)->whereNull('deleted_at')->first();if(!$c)throw new Failure('course_unavailable',404);$u=Access::user($r->session()->get('uid'));if((!$u||$u->must_change_password)&&$c->guest_access!=='public')throw new Failure('forbidden',403);$v=$r->validate(['q'=>'required|string|min:1|max:200','page'=>'integer|min:1|max:100000']);$q=DB::table('subtitle_units as s')->join('lessons as l','l.id','=','s.lesson_id')->where('l.course_id',$course)->whereNull('l.deleted_at')->whereNull('s.deleted_at')->whereRaw('COALESCE(s.current_text,s.original_text) ILIKE ?',['%'.addcslashes($v['q'],'%_\\').'%']);\App\Content\SubtitleText::visible($q,'COALESCE(s.current_text,s.original_text)');$total=(clone$q)->count();$page=(int)($v['page']??1);return ['units'=>$q->select('s.*','l.name as lesson_name')->orderByDesc('s.id')->offset(($page-1)*30)->limit(30)->get()->map(fn($u)=>Access::unit($u)),'total'=>$total,'page'=>$page,'per_page'=>30];})->whereNumber('course');
Route::post('/api/admin/lessons/{lesson}/purge',function(Request $r,int $lesson)use($settingsActor){$u=$settingsActor($r,true);$v=$r->validate(['confirmed'=>'required|accepted','confirm_name'=>'required|string|max:200']);return DB::transaction(function()use($lesson,$u,$v){$l=DB::table('lessons')->where('id',$lesson)->lockForUpdate()->first();$u=\App\Content\MutationActor::lock($u,true);if(!$l||!$l->deleted_at||$l->status!=='ended')throw new Failure('purge_requires_deleted_lesson',409);if(!hash_equals($l->name,$v['confirm_name']))throw new Failure('purge_name_mismatch',422);if($l->purge_status==='purged')return ['status'=>'purged'];if(in_array($l->purge_status,['queued','processing']))return ['status'=>$l->purge_status];DB::table('lessons')->where('id',$lesson)->update(['purge_status'=>'queued']);DB::table('audit')->insert(['lesson_id'=>$lesson,'user_id'=>$u->id,'action'=>'lesson.purge_requested']);\App\Jobs\PurgeLesson::dispatch($lesson)->afterCommit();return ['status'=>'queued'];});})->whereNumber('lesson');
Route::get('/api/lessons/{lesson}/download',function(Request $r,int $lesson){$u=Access::user($r->session()->get('uid'));Access::member($u);$l=Access::lesson($lesson,$u,$r->session()->getId());if(!Settings::policies()['audio_download']||!DB::table('courses')->where('id',$l->course_id)->value('allow_audio_download'))throw new Failure('recording_download_disabled',403);$recording=DB::table('recordings')->where('lesson_id',$lesson)->where('status','playable')->first();if(!$recording||$l->archive_status!=='playable')throw new Failure('recording_not_ready',409);try{$storage=\App\Storage\StorageRegistry::resolve($recording->storage_version);$name=mb_substr(preg_replace('/[\x00-\x1f\x7f\/\\\\:"<>|?*]+/u','_',$l->name),0,100).'.m4a';$url=$storage->presignedGet($recording->object_key,$name);}catch(\Throwable){throw new Failure('storage_configuration_version_unavailable',503);}return redirect()->away($url)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');})->whereNumber('lesson');
